import{_ as t,C as r,o,c as n,E as i,a2 as l}from"./chunks/framework.Cm6XCzck.js";const b=JSON.parse('{"title":"Agent 历史迁移必须保留语义，而不只是搬运文件","description":"","frontmatter":{"title":"Agent 历史迁移必须保留语义，而不只是搬运文件","date":"2026-08-06","column":"open-source-engineering","category":"daily","summary":"回滚、压缩和迟到事件会让物理记录顺序偏离逻辑会话边界；可靠迁移必须先重建语义，再通过带 journal 的幂等阶段发布和恢复。","item_id":"Q-20260806-03","source_research_object":"research/analysis/Q-20260806-03-rollout-migration-recovery.md","source_reading_result":"research/reading/Q-20260806-03-rollout-migration-recovery.md","lifecycle":"Published","evidence_status":"Completed","citation_status":"Completed","editing_status":"Completed","publication_authorized":true,"outline":"deep","cover":"/assets/covers/daily-2026-08-06-semantic-migration-recovery-cover-v2.jpg"},"headers":[],"relativePath":"zh/engineering/2026-08-06-semantic-migration-recovery.md","filePath":"zh/engineering/2026-08-06-semantic-migration-recovery.md","lastUpdated":1787407830000}'),d={name:"zh/engineering/2026-08-06-semantic-migration-recovery.md"};function c(s,e,h,u,m,p){const a=r("ArticleCover");return o(),n("div",null,[i(a,{image:"/assets/covers/daily-2026-08-06-semantic-migration-recovery-cover-v2.jpg",kicker:"开源工程 · 每日研究",title:"Agent 历史迁移必须保留语义，而不只是搬运文件",summary:"回滚、压缩和迟到事件会让物理记录顺序偏离逻辑会话边界；可靠迁移必须先重建语义，再通过带 journal 的幂等阶段发布和恢复。",version:"Q-20260806-03",status:"Daily Runtime V5 · 2026-08-06",languageHref:"/en/engineering/2026-08-06-semantic-migration-recovery",languageLabel:"English"}),e[0]||(e[0]=l(' # Agent 历史迁移必须保留语义，而不只是搬运文件 <p>Agent rollout 的持久记录可能经历回滚、压缩、父子历史复制和迟到生命周期事件。此时，物理顺序不再等于逻辑会话含义。逐行复制可以保留字节，却可能恢复出错误的可见历史。</p><h2 id="核心判断" tabindex="-1">核心判断 <a class="header-anchor" href="#核心判断" aria-label="Permalink to &quot;核心判断&quot;">​</a></h2><p><strong>Agent 历史迁移应被定义为版本化语义转换，而不是文件格式转换。</strong> 转换需要明确不变量、逻辑边界和降级项；跨 JSONL 与 SQLite 的发布应采用持久 journal 与幂等阶段，并把结果称为“可恢复”，除非真正证明了全局原子性。</p><h2 id="来源" tabindex="-1">来源 <a class="header-anchor" href="#来源" aria-label="Permalink to &quot;来源&quot;">​</a></h2><p>本文唯一分析输入是获准进入 Production 的 Research Object。Production 没有重新读取提交差异来开展新分析，也不把单一维护者变更和测试提升为 fleet-scale 保证。</p><h2 id="观察" tabindex="-1">观察 <a class="header-anchor" href="#观察" aria-label="Permalink to &quot;观察&quot;">​</a></h2><p>Research Object 描述了四个关键机制：按逻辑 turn ownership 分配记录；消费 rollback 事件并保留必要 compaction anchor；在可证明安全检查点时进行有界反向重放，否则回退到完整容错重放；通过 flush、sync、rename 发布文件，并以 pending journal 跨越 JSONL 已发布而 SQLite 尚未完成的非原子区间。</p><h2 id="比较" tabindex="-1">比较 <a class="header-anchor" href="#比较" aria-label="Permalink to &quot;比较&quot;">​</a></h2><table tabindex="0"><thead><tr><th>方法</th><th>保留对象</th><th>主要保证</th><th>明确边界</th></tr></thead><tbody><tr><td>原样复制</td><td>字节和物理顺序</td><td>文件内容未改写</td><td>可能破坏逻辑可见历史</td></tr><tr><td>语义重放</td><td>turn ownership、rollback、compaction 与子 Agent 边界</td><td>恢复预期会话意义</td><td>依赖不变量与容错策略</td></tr><tr><td>原子 rename</td><td>单文件发布</td><td>读者看到旧文件或新文件</td><td>不覆盖多存储事务</td></tr><tr><td>Journaled recovery</td><td>跨 JSONL/SQLite 的发布意图和阶段</td><td>崩溃后可继续或修复</td><td>是可恢复协议，不是分布式原子事务</td></tr></tbody></table><p>表格区分了字节保存、语义恢复、单文件原子性和跨存储可恢复性，避免把不同保证混为一谈。</p><h2 id="讨论" tabindex="-1">讨论 <a class="header-anchor" href="#讨论" aria-label="Permalink to &quot;讨论&quot;">​</a></h2><p>可靠迁移应先完成 semantic canonicalization，再执行 durable publication。逻辑 turn id 能处理迟到记录，而简单删除物理后缀可能误删仍属于有效 turn 的证据。pending journal 的作用是保留跨存储过渡意图，使恢复者能幂等地完成或修复，而不是假装存在一个并未建立的全局事务。</p><p>有界重放也必须是“证明后优化”：只有安全检查点成立时才缩小重放范围，否则回退到完整容错重放。回退可能增加成本或保留重复，但它比在不确定边界上做激进裁剪更保守。</p><h2 id="工程影响" tabindex="-1">工程影响 <a class="header-anchor" href="#工程影响" aria-label="Permalink to &quot;工程影响&quot;">​</a></h2><p>对 CodeFlowMu，可把迁移拆成 Prepare、Transform、Validate、Publish、Complete 与 Recover 阶段，并为每阶段配置幂等键。任何跨多个存储或投影的逻辑迁移都应有 durable pending journal。</p><p>迁移 manifest 应包含源/目标版本、记录数量、逻辑边界决定、跳过项、fallback 路径、journal 阶段和验证结果。FCoP 的 append-only 历史与当前生命周期事实保持权威，派生索引和 Runtime 投影可以重建，但不能反向改写协议历史。</p><h2 id="边界与反证" tabindex="-1">边界与反证 <a class="header-anchor" href="#边界与反证" aria-label="Permalink to &quot;边界与反证&quot;">​</a></h2><p>证据是一项已合并维护者变更和相关测试，不是独立或大规模生产验证。损坏或超大记录可能被跳过或失败；文件系统 rename、fsync 和目录同步具有平台差异；journal 不是分布式事务；来源没有提供吞吐、恢复时长、争用或生产数据丢失指标。</p><h2 id="未来工作" tabindex="-1">未来工作 <a class="header-anchor" href="#未来工作" aria-label="Permalink to &quot;未来工作&quot;">​</a></h2><p>需要定义迁移前后模型可见上下文的可比较不变量，确定何时损坏记录必须阻断而不是降级，设计并发 writer/recoverer 协调，以及把哪些吞吐、fallback 和恢复指标作为发布门禁。</p><h2 id="可视化说明" tabindex="-1">可视化说明 <a class="header-anchor" href="#可视化说明" aria-label="Permalink to &quot;可视化说明&quot;">​</a></h2><p>配图把 Prepare 到 Recover 的阶段与 pending journal、JSONL、SQLite 分开表示。它是 Research Center 基于 Research Object 的生命周期综合，不声称跨存储全局原子性。</p><h2 id="证据与引用" tabindex="-1">证据与引用 <a class="header-anchor" href="#证据与引用" aria-label="Permalink to &quot;证据与引用&quot;">​</a></h2><ol><li><a href="https://github.com/joinwell52-AI/joinwell52/blob/main/research/analysis/Q-20260806-03-rollout-migration-recovery.md" target="_blank" rel="noreferrer">Research Object</a>：本文唯一分析输入，包含语义迁移判断、可恢复边界、反证和工程影响。</li><li><a href="https://github.com/joinwell52-AI/joinwell52/blob/main/research/reading/Q-20260806-03-rollout-migration-recovery.md" target="_blank" rel="noreferrer">Reading Result</a>：Research Object 声明的证据边界与来源追溯记录；本文不从该记录重新分析。</li></ol>',25))])}const _=t(d,[["render",c]]);export{b as __pageData,_ as default};
